 			if err != nil {
 				continue
 			}
-			if strings.EqualFold(info.Host, host) && isDerivableProtocol(info.Protocol) {
+			if strings.EqualFold(info.Host, host) && isDirectGitTransport(info.Protocol) {
 				return info, true
 			}
 		}

