// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
func (s *EntireSettings) IsSummarizeEnabled() bool {
	if s.StrategyOptions == nil {
		return false
	}
	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
	if !ok {
		return false
	}
	enabled, ok := summarizeOpts["enabled"].(bool)
	if !ok {
		return false
	}
	return enabled
}

// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
type CheckpointRemoteConfig struct {
	Provider string // e.g., "github"
	Repo     string // e.g., "org/checkpoints-repo"
}

// Owner returns the owner portion of the repo field (before the slash).
// Returns empty string if the repo field doesn't contain a slash.
func (c *CheckpointRemoteConfig) Owner() string {
	parts := strings.SplitN(c.Repo, "/", 2)
	if len(parts) < 2 {
		return ""
	}
	return parts[0]
}

// GetCheckpointRemote returns the configured checkpoint remote.
// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
// Returns nil if not configured, wrong type, or missing required fields.
func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
	if s.StrategyOptions == nil {
		return nil
	}
	val, ok := s.StrategyOptions["checkpoint_remote"]
	if !ok {
		return nil
	}
	m, ok := val.(map[string]any)
	if !ok {
		return nil
	}
	provider, providerOK := m["provider"].(string)
	repo, repoOK := m["repo"].(string)
	if !providerOK || !repoOK || provider == "" || repo == "" {
		return nil
	}
	if !strings.Contains(repo, "/") {
		return nil
	}
	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}

//go:build e2e

package tests

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/entire"
	"github.com/entireio/cli/e2e/testutil"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestResumeFromClonedRepo: agent creates a file on a feature branch and user
// commits, then the repo is cloned (simulating a teammate). The clone has no
// local checkpoint metadata ref for the active suite mode. `entire resume feature`
// should fetch that ref automatically and restore the session.
func TestResumeFromClonedRepo(t *testing.T) {
	testutil.ForEachAgent(t, 3*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		// Set up a bare remote so we can push and clone.
		bareDir := testutil.SetupBareRemote(t, s)

		// Commit files from `entire enable` so main has a clean working tree.
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")
		s.Git(t, "push")

		// Do agent work on a feature branch.
		s.Git(t, "checkout", "-b", "feature")

		_, err := s.RunPrompt(t, ctx,
			"create a file at docs/hello.md with a paragraph about greetings. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add hello doc")
		testutil.WaitForCheckpoint(t, s, 30*time.Second)
		checkpointID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		sessionMeta := testutil.WaitForSessionMetadata(t, s.Dir, checkpointID, 0, 30*time.Second)

		// Push feature branch and checkpoint refs to the bare remote.
		s.Git(t, "push", "-u", "origin", "feature")
		testutil.PushCheckpointRefs(t, s.Dir)

		// Clone the repo to a new directory (simulating a teammate).
		cloneDir := t.TempDir()
		if resolved, symErr := filepath.EvalSymlinks(cloneDir); symErr == nil {
			cloneDir = resolved
		}
		// Remove the dir because git clone wants to create it.
		require.NoError(t, os.RemoveAll(cloneDir))
		testutil.Git(t, "", "clone", bareDir, cloneDir)
		testutil.Git(t, cloneDir, "config", "user.name", "E2E Clone")
		testutil.Git(t, cloneDir, "config", "user.email", "e2e-clone@test.local")

		// Verify no committed checkpoint exists locally in the clone yet.
		require.False(t, testutil.CheckpointsPresent(cloneDir), "checkpoint metadata should not exist locally in clone")

		// Create the local feature branch (clone only has origin/feature as remote tracking ref).
		// Then switch back to the default branch so resume can switch to it.
		mainClone := testutil.GitOutput(t, cloneDir, "branch", "--show-current")
		testutil.Git(t, cloneDir, "checkout", "feature")
		testutil.Git(t, cloneDir, "checkout", mainClone)

		// Enable entire in the cloned repo and commit the enable files.
		entire.Enable(t, cloneDir, s.Agent.EntireAgent())
		testutil.CommitIfDirty(t, cloneDir, "Enable entire in clone")

		// Run resume from the clone — should fetch metadata and succeed.
		out, err := entire.Resume(cloneDir, "feature")
		require.NoError(t, err, "entire resume failed in clone: %s", out)

		current := testutil.GitOutput(t, cloneDir, "branch", "--show-current")
		assert.Equal(t, "feature", current, "should be on feature branch after resume")
		assert.Contains(t, out, "To continue", "resume output should show resume instructions")

		// Verify a committed checkpoint now exists locally.
		assert.True(t, testutil.CheckpointsPresent(cloneDir), "checkpoint metadata should exist locally after resume")

		if restoredTranscript, ok := testutil.RestoredSessionTranscriptPath(t, cloneDir, sessionMeta); ok {
			_, err = os.Stat(restoredTranscript)
			assert.NoError(t, err, "restored session transcript should exist at %s after resume", restoredTranscript)
		}
	})
}

// TestResumeMetadataBranchAlreadyLocal: same setup as TestResumeFromClonedRepo
// but the checkpoint metadata ref already exists locally. Resume should still work
// (fetch updates local to latest).
func TestResumeMetadataBranchAlreadyLocal(t *testing.T) {
	testutil.ForEachAgent(t, 3*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		mainBranch := testutil.GitOutput(t, s.Dir, "branch", "--show-current")

		// Commit files from `entire enable` so main has a clean working tree.
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")

		// Do agent work on a feature branch.
		s.Git(t, "checkout", "-b", "feature")

		_, err := s.RunPrompt(t, ctx,
			"create a file at docs/hello.md with a paragraph about greetings. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add hello doc")
		testutil.WaitForCheckpoint(t, s, 30*time.Second)

		// Switch back to main and resume the feature branch.
		// The metadata branch exists locally (was created during commit).
		s.Git(t, "checkout", mainBranch)

		out, err := entire.Resume(s.Dir, "feature")
		require.NoError(t, err, "entire resume failed: %s", out)

		current := testutil.GitOutput(t, s.Dir, "branch", "--show-current")
		assert.Equal(t, "feature", current, "should be on feature branch after resume")
		assert.Contains(t, out, "To continue", "resume output should show resume instructions")
	})
}

//go:build integration

package integration

import (
	"os/exec"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// =============================================================================
// P0 -- PrePush Basic Flow
// =============================================================================

// TestPrePush_PushesCheckpointBranchToOrigin verifies that PrePush pushes the
// committed checkpoints to a bare remote after condensation, under both the
// git-branch (v1 branch) and git-refs (per-checkpoint refs) backends.
func TestPrePush_PushesCheckpointBranchToOrigin(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		// Set up bare remote
		bareDir := env.SetupBareRemote()

		// Create a session, make changes, checkpoint, and commit (triggers condensation)
		checkpointID := createCheckpointedCommit(t, env, "Add auth module", "auth.go", "package auth", "Add auth module")

		// Verify condensation happened locally
		if !env.CheckpointsPresentLocally() {
			t.Fatal("checkpoints should exist locally after condensation")
		}

		// Run PrePush (simulates what happens during git push)
		env.RunPrePush("origin")

		// Verify the checkpoints arrived on the remote
		if !env.CheckpointsPresentOnRemote(bareDir) {
			t.Error("checkpoints should exist on bare remote after PrePush")
		}

		// Verify the specific checkpoint is on the remote
		if checkpointID == "" {
			t.Fatal("should have a checkpoint ID after condensation")
		}
		if !env.CheckpointExistsOnRemote(bareDir, checkpointID) {
			t.Errorf("checkpoint %s should exist on remote", checkpointID)
		}
	})
}

// TestPrePush_NoOpWhenNoCheckpoints verifies that PrePush is a no-op
// when no sessions or checkpoints exist.
func TestPrePush_NoOpWhenNoCheckpoints(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		bareDir := env.SetupBareRemote()

		// Run PrePush without any session activity
		env.RunPrePush("origin")

		// No checkpoints should exist on remote
		if env.CheckpointsPresentOnRemote(bareDir) {
			t.Error("checkpoints should NOT exist on remote when none were created")
		}
	})
}

// TestPrePush_IdempotentWhenAlreadyPushed verifies that pushing twice
// with no new checkpoints is a no-op (idempotent).
func TestPrePush_IdempotentWhenAlreadyPushed(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		bareDir := env.SetupBareRemote()

		// Create session, commit, push
		_ = createCheckpointedCommit(t, env, "Initial work", "main.go", "package main", "Initial work")

		// First push
		env.RunPrePush("origin")

		if !env.CheckpointsPresentOnRemote(bareDir) {
			t.Fatal("checkpoints should exist after first push")
		}

		// Get remote checkpoint state before second push
		stateBefore := env.RemoteCheckpointState(bareDir)

		// Second push (no new checkpoints)
		env.RunPrePush("origin")

		// Remote state should be unchanged
		stateAfter := env.RemoteCheckpointState(bareDir)
		if stateBefore != stateAfter {
			t.Errorf("remote checkpoint state should be unchanged after idempotent push:\nbefore=%s\nafter=%s", stateBefore, stateAfter)
		}
	})
}

// =============================================================================
// P0 -- Checkpoint Remote Config
// =============================================================================

// TestPrePush_PushDisabledSkipsCheckpoints verifies that push_sessions: false
// disables checkpoint push.
func TestPrePush_PushDisabledSkipsCheckpoints(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		bareDir := env.SetupBareRemote()

		// Configure push_sessions: false
		env.PatchSettings(map[string]any{
			"strategy_options": map[string]any{
				"push_sessions": false,
			},
		})

		// Create session, checkpoint, and commit
		_ = createCheckpointedCommit(t, env, "Some work", "work.go", "package work", "Some work")

		// Verify checkpoint was created locally
		if !env.CheckpointsPresentLocally() {
			t.Fatal("should have local checkpoints after condensation")
		}

		// PrePush should skip checkpoints when push_sessions is false
		env.RunPrePush("origin")

		// Checkpoints should NOT be on remote
		if env.CheckpointsPresentOnRemote(bareDir) {
			t.Error("checkpoints should NOT be on remote when push_sessions is false")
		}
	})
}

// TestPrePush_CheckpointRemoteRoutesToSeparateRemote verifies that checkpoint data
// can be selectively pushed to a separate remote.
//
// This is a data routing verification test. It validates that when the production
// code's pushRefIfNeeded is called with different targets for checkpoints,
// the branches land on the correct remotes with correct data.
//
// Why not test through PrePush directly: resolvePushSettings derives the checkpoint
// URL from origin's protocol (SSH/HTTPS). Since integration tests use local file
// paths as remotes, remote.ParseURL fails and resolvePushSettings falls back to
// origin. The URL derivation logic is unit-tested in checkpoint/remote/util_test.go
// (TestDeriveCheckpointURLFromInfo) and checkpoint_remote_test.go
// (TestResolvePushSettings_WithCheckpointRemote_*).
//
// The pushRefIfNeeded function (which PrePush calls with the resolved target)
// is exercised in push_common_test.go:TestPushRefIfNeeded_LocalBareRepo_PushesSuccessfully,
// verifying it works with local bare repo paths.
//
// git-branch only: this test directly pushes the v1 branch via env.GitPush to
// verify data routing. checkpoint_remote routing for git-refs per-checkpoint
// refs is separate future work (test plan B5, "gr: N/A until checkpoint_remote
// applies to refs"), so this stays on the default (git-branch) backend.
func TestPrePush_CheckpointRemoteRoutesToSeparateRemote(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	// Set up two bare remotes: origin for user code, checkpoint remote for checkpoints
	bareOrigin := env.SetupBareRemote()
	bareCheckpoint := env.SetupNamedBareRemote("checkpoint-store")

	// Create session, checkpoint, and commit
	checkpointID := createCheckpointedCommit(t, env, "Add router", "router.go", "package router", "Add router")

	// Verify local checkpoint branch exists
	if !env.BranchExists(paths.MetadataBranchName) {
		t.Fatal("should have local checkpoint branch after condensation")
	}

	// Simulate checkpoint_remote routing: push checkpoints to the checkpoint bare repo.
	// This mirrors what PrePush does when resolvePushSettings returns a checkpointURL.
	env.GitPush(bareCheckpoint, paths.MetadataBranchName)

	// Checkpoints should be on checkpoint remote, NOT on origin
	if !env.BranchExistsOnRemote(bareCheckpoint, paths.MetadataBranchName) {
		t.Error("entire/checkpoints/v1 should exist on checkpoint remote")
	}
	if env.BranchExistsOnRemote(bareOrigin, paths.MetadataBranchName) {
		t.Error("entire/checkpoints/v1 should NOT be on origin when routed to checkpoint remote")
	}

	// Verify checkpoint data arrived on checkpoint remote
	summaryPath := CheckpointSummaryPath(checkpointID)
	if !fileExistsOnRemoteBranch(t, bareCheckpoint, summaryPath) {
		t.Errorf("checkpoint metadata should exist on checkpoint remote at %s", summaryPath)
	}
}

// REDACTED verifies that when
// origin is a local file path (not an SSH/HTTPS URL), resolvePushSettings cannot
// derive a checkpoint URL and checkpoints fall back to origin.
//
// This exercises the integration behavior: when checkpoint_remote is configured but
// the push remote URL cannot be parsed (local file path), checkpoints still land on
// origin. The exact fork detection logic (owner mismatch) is unit-tested in
// checkpoint_remote_test.go:TestResolvePushSettings_ForkDetection.
func REDACTED(t *testing.T) {
	t.Parallel()
	ForEachBackend(t, func(t *testing.T, backend string) {
		env := NewFeatureBranchEnv(t)
		env.CheckpointStore = backend

		bareDir := env.SetupBareRemote()

		// Configure checkpoint_remote with a different owner than origin.
		// Since our bare remote is a local path (not a URL), resolvePushSettings cannot
		// parse it via remote.ParseURL and falls back to origin. The unit test
		// TestResolvePushSettings_ForkDetection in checkpoint_remote_test.go validates
		// the exact fork detection logic with real URL parsing.
		env.PatchSettings(map[string]any{
			"strategy_options": map[string]any{
				"checkpoint_remote": map[string]any{
					"provider": "github",
					"repo":     "different-org/checkpoints",
				},
			},
		})

		// Create session, checkpoint, and commit
		_ = createCheckpointedCommit(t, env, "Add middleware", "middleware.go", "package middleware", "Add middleware")

		// Run PrePush -- with a local path remote, checkpoint URL derivation will fail
		// (remote.ParseURL can't parse local paths), so checkpoints fall back to origin.
		env.RunPrePush("origin")

		// Checkpoints should be on origin (fallback behavior)
		if !env.CheckpointsPresentOnRemote(bareDir) {
			t.Error("checkpoints should be on origin when checkpoint_remote is unavailable (fork/fallback)")
		}
	})
}

// =============================================================================
// P0 -- Clone and Resume
//
// The clone/fetch tests below stay on the default git-branch backend: they fetch
// and read the v1 branch tree directly (FetchMetadataBranch, FileExistsInBranch).
// git-refs cross-machine fetch goes through the on-demand RefFetcher, a distinct
// path covered separately (test plan C2, git-refs only) rather than by
// parameterizing these v1-tree assertions.
// =============================================================================

// createCheckpointedCommit is a helper that creates a session with a single file change,
// runs the full lifecycle (prompt submit -> write -> stop -> commit), and returns the
// session and checkpoint ID. This reduces boilerplate in tests where the session setup
// is not the focus.
func createCheckpointedCommit(t *testing.T, env *TestEnv, prompt, fileName, fileContent, commitMsg string) string {
	t.Helper()

	session := env.NewSession()
	transcriptPath := session.CreateTranscript(prompt, []FileChange{
		{Path: fileName, Content: fileContent},
	})

	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(session.ID, prompt, transcriptPath); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	env.WriteFile(fileName, fileContent)
	env.GitAdd(fileName)

	if err := env.SimulateStop(session.ID, transcriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	env.GitCommitWithShadowHooks(commitMsg, fileName)

	return env.LatestCheckpointID()
}

// TestCloneAndResume_FetchesCheckpointMetadata verifies that after pushing
// checkpoints to a remote, cloning the repo and fetching the metadata branch
// brings the checkpoint data locally.
//
// Note: This test uses env.FetchMetadataBranch (raw git fetch) rather than
// triggering fetchMetadataBranchIfMissing via the production code path, because
// fetchMetadataBranchIfMissing uses OpenRepository which requires CWD to be
// inside the repo (incompatible with t.Parallel). The production function is
// tested directly in checkpoint_remote_test.go (TestFetchBranchIfMissing_*).
// This test verifies the "data arrives and is usable" property.
func TestCloneAndResume_FetchesCheckpointMetadata(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	bareDir := env.SetupBareRemote()

	// Repo A: create session, checkpoint, commit, push
	checkpointID := createCheckpointedCommit(t, env, "Build login page", "login.go", "package login", "Build login page")
	t.Logf("Original checkpoint ID: %s", checkpointID)

	// Push user branch + checkpoint branches to remote
	env.GitPush("origin", "HEAD")
	env.RunPrePush("origin")

	// Clone into repo B
	cloneEnv := env.CloneFrom(bareDir)

	// Fetch the metadata branch (simulates what fetchMetadataBranchIfMissing does)
	cloneEnv.FetchMetadataBranch(bareDir)

	// Now the metadata branch should exist locally in the clone
	if !cloneEnv.BranchExists(paths.MetadataBranchName) {
		t.Fatal("entire/checkpoints/v1 should exist in clone after fetch")
	}

	// Verify the checkpoint data is present
	summaryPath := CheckpointSummaryPath(checkpointID)
	if !cloneEnv.FileExistsInBranch(paths.MetadataBranchName, summaryPath) {
		t.Errorf("checkpoint metadata should exist in clone at %s", summaryPath)
	}
}

// TestCloneAndResume_SessionListingWorksAfterClone verifies that checkpoint
// metadata can be enumerated after cloning and fetching the metadata branch.
func TestCloneAndResume_SessionListingWorksAfterClone(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	bareDir := env.SetupBareRemote()

	// Repo A: create session, checkpoint, commit, push
	checkpointID := createCheckpointedCommit(t, env, "Implement auth", "auth.go", "package auth", "Implement auth")

	// Push everything
	env.GitPush("origin", "HEAD")
	env.RunPrePush("origin")

	// Clone and fetch metadata
	cloneEnv := env.CloneFrom(bareDir)
	cloneEnv.FetchMetadataBranch(bareDir)

	// List checkpoints from the clone by scanning the metadata branch tree
	checkpoints := listCheckpointsInDir(t, cloneEnv.RepoDir)

	if len(checkpoints) == 0 {
		t.Fatal("should find checkpoints from original repo after clone")
	}

	// Verify our checkpoint is in the list
	found := false
	for _, cp := range checkpoints {
		if cp == checkpointID {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("checkpoint %s from original repo should be in list, got: %v", checkpointID, checkpoints)
	}
